const u=r=>Math.round((Number(r)+Number.EPSILON)*100)/100;function b(r,e,t,n){const o=Number.isFinite(Number(r))?Number(r):0,N=Number.isFinite(Number(e))?Number(e):0,m=Number.isFinite(Number(t))?Number(t):0,s=u(o*N),c=u(s*m/100);if(n==="INTER_STATE")return{gstRate:m,amount:s,cgst:0,sgst:0,igst:c,lineTotal:u(s+c)};const a=u(c/2);return{gstRate:m,amount:s,cgst:a,sgst:a,igst:0,lineTotal:u(s+a+a)}}function i(r){return{totalQty:u(r.reduce((e,t)=>e+Number(t.qty||0),0)),taxableAmount:u(r.reduce((e,t)=>e+Number(t.amount||0),0)),cgst:u(r.reduce((e,t)=>e+Number(t.cgst||0),0)),sgst:u(r.reduce((e,t)=>e+Number(t.sgst||0),0)),igst:u(r.reduce((e,t)=>e+Number(t.igst||0),0)),grandTotal:u(r.reduce((e,t)=>e+Number(t.lineTotal||0),0))}}export{b as c,i as s};
